// One weapon's tuning. A designer edits this table and nothing else.
/* table WeaponConfig — TABLE-wire storage: relocatable, bounded. C has no member
   initializers, so the declared defaults live in weapon_config_reset and nowhere
   else — one definition of what a default is (docs/SPEC-TABLES.md) */
typedef struct WeaponConfig {
    //  Damage per hit, before armor.
    //
    // The armor curve is written "hardness \ hit" in the design notes,
    // and the backslash is part of the name.
    float damage;
    float speed;
    int32_t penetration;
    uint32_t channel;
    uint8_t homing;
    Effect effect;
} WeaponConfig;

/* table LoadoutConfig — TABLE-wire storage: relocatable, bounded. C has no member
   initializers, so the declared defaults live in loadout_config_reset and nowhere
   else — one definition of what a default is (docs/SPEC-TABLES.md) */
typedef struct LoadoutConfig {
    Grade grade;
    Grade grades[4]; /* used count beside it; count in [0, 4] */
    int32_t grades_count;
    Grade podium[3];
    Perks perks;
    WeaponConfig primary;
    WeaponConfig backups[2];
    Attachment attachments[8]; /* used count beside it; count in [0, 8] */
    int32_t attachments_count;
} LoadoutConfig;

/* table ProfileConfig — TABLE-wire storage: relocatable, bounded. C has no member
   initializers, so the declared defaults live in profile_config_reset and nowhere
   else — one definition of what a default is (docs/SPEC-TABLES.md) */
typedef struct ProfileConfig {
    char name[32 + 1]; /* string(32): N + 1 for the terminator the wire does not carry */
    int32_t name_length;
    uint8_t icon[16]; /* bytes(16): fixed buffer, used length beside it */
    int32_t icon_length;
    uint32_t experience;
    int8_t tilt;
    int16_t heading;
    int64_t timestamp;
    uint8_t badge;
    uint16_t port;
    uint64_t epoch;
    double precision;
    float ratings[4];
    uint8_t has_loadout;

    /* has_loadout — guarded fields stay off the wire when the guard says so;
       a read's prefilled defaults stand in for the untaken side */
    LoadoutConfig loadout;
} ProfileConfig;

/* table RootConfig — TABLE-wire storage: relocatable, bounded. C has no member
   initializers, so the declared defaults live in root_config_reset and nowhere
   else — one definition of what a default is (docs/SPEC-TABLES.md) */
typedef struct RootConfig {
    char version_note[16 + 1]; /* string(16): N + 1 for the terminator the wire does not carry */
    int32_t version_note_length;
    WeaponConfig weapons[8]; /* used count beside it; count in [0, 8] */
    int32_t weapons_count;
    ProfileConfig profiles[4]; /* used count beside it; count in [0, 4] */
    int32_t profiles_count;
} RootConfig;

